/* Action queues share the same obligation, transfer, and agreement records. */
const todayISO=()=>localDate(today);
const obligations=()=>Workflows.obligations(state,todayISO());
const renewals=()=>Workflows.renewalItems(state,todayISO());
const tenantById=id=>state.tenants.find(t=>t.id===id);
const obligationById=id=>obligations().find(o=>o.id===id);
const renewalById=id=>renewals().find(o=>o.id===id);
const transferLabels={review:'Perlu diperiksa',deferred:'Ditunda',paid:'Terverifikasi',rejected:'Ditolak'};
function workflowTabs(items){if(!items.some(([id])=>id===workflowTab))workflowTab=items[0][0];return `<div class="tabs workflow-tabs" aria-label="Status pekerjaan">${items.map(([id,label,count])=>`<button class="${id===workflowTab?'active':''}" aria-pressed="${id===workflowTab}" onclick="workflowTab='${id}';render()">${label}${count!==undefined?` <span>${count}</span>`:''}</button>`).join('')}</div>`}
function setRecordTab(tab){recordTab=tab;search='';render()}
function moreHTML(){return `<div class="more-links">${[['payments','Ledger sewa','Tagihan dan alokasi pembayaran per bulan'],['records','Penghuni & kamar','Kesepakatan sewa dan ketersediaan kamar'],['settings','Pengaturan pesan','Template WhatsApp dan ekspor data']].map(([id,title,note])=>`<button class="panel more-link" onclick="go('${id}')"><b>${title} →</b><small>${note}</small></button>`).join('')}</div>`}
function overviewHTML(){
 const bills=obligations(),collection=bills.filter(o=>['needs_contact','follow_up','awaiting_payment'].includes(o.state)),reviews=state.payments.filter(p=>['review','deferred'].includes(p.status)),renew=renewals().filter(o=>!['renewed','closed','outside_window'].includes(o.state));
 const current=localDate(today).slice(0,7),tenants=state.tenants.filter(t=>t.start.slice(0,7)<=current),totals=ledgerTotals(tenants,current);
 return `<div class="notice">Hari ini, ${dateLabel(today)} · Antrean mencakup pekerjaan belum selesai dari semua periode.</div><div class="queue-cards">${[['verify','Verifikasi pembayaran',reviews.length,'Transfer menunggu pemeriksaan, termasuk yang ditunda.','Periksa pembayaran'],['collect','Tagih sewa',collection.length,'Tagihan perlu dihubungi atau menunggu pembayaran.','Buka penagihan'],['renew','Perpanjangan sewa',renew.length,'Keputusan perpanjangan dan rencana keluar.','Buka perpanjangan']].map(([id,title,count,note,action])=>`<section class="panel queue-card"><span class="eyebrow">${title}</span><strong>${count}</strong><p>${count?note:'Tidak ada pekerjaan yang perlu ditangani. ✓'}</p><button class="secondary" onclick="go('${id}')">${action} →</button></section>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Keuangan · ${periodName(current)}</h2><p>Alokasi sewa bulanan dari transfer terverifikasi.</p></div><button class="text-button" onclick="month=Billing.date('${current}',1);go('payments')">Buka ledger →</button></div><div class="finance-strip"><div><small>Tagihan</small><b>${money(totals.charge)}</b></div><div><small>Terbayar</small><b>${money(totals.paid)}</b></div><div><small>Sisa</small><b>${money(totals.balance)}</b></div></div></section>`;
}
function urgency(o){const d=Math.round((new Date(o.due+'T00:00:00')-today)/86400000);return `<span class="badge ${d<0?'late':'soon'}">${d<0?'Terlambat '+Math.abs(d)+' hari':d===0?'Jatuh tempo hari ini':'Jatuh tempo '+dateLabel(new Date(o.due+'T00:00:00'))}</span>`}
function collectionHTML(){
 const list=obligations(),states=[['needs_contact','Perlu dihubungi'],['awaiting_payment','Menunggu pembayaran'],['follow_up','Perlu tindak lanjut']];
 const tabs=workflowTabs(states.map(([id,label])=>[id,label,list.filter(o=>o.state===id).length]));
 const rows=list.filter(o=>o.state===workflowTab).sort((a,b)=>a.due.localeCompare(b.due));
 return `<div class="notice">Satu tagihan per periode sewa. Transfer yang masih diperiksa menghentikan pengingat untuk bulan yang ditanggung. Membuka WhatsApp belum berarti pesan terkirim.</div><section class="panel"><div class="panel-head"><div><h2>Antrean penagihan</h2><p>Semua periode · tanpa filter bulan</p></div><button class="text-button" onclick="go('settings')">Template pesan →</button></div>${tabs}${rows.map(o=>{const t=tenantById(o.tenant);return `<article class="work-row"><div class="work-person"><span class="avatar sage">${esc(initials(t))}</span><div><b>${esc(t.name)}</b><small>Kamar ${esc(room(t).name)} · ${rangeLabel(o.period,o.months)}</small><small>${o.followUp?'Tindak lanjut: '+esc(o.followUp):'Belum ada jadwal tindak lanjut'}</small></div></div><div class="work-amount"><b>${money(o.uncovered)}</b><small>belum dibayar / dicatat</small>${urgency(o)}</div><div class="work-actions"><button class="primary" onclick="reminder('${o.tenant}','${o.id}')">${o.state==='follow_up'?'Kirim tindak lanjut':'Siapkan pesan'}</button><button class="text-button" onclick="recordPayment('${o.tenant}','${o.period}')">Catat pembayaran</button>${o.state==='awaiting_payment'?`<button class="text-button" onclick="scheduleFollowUp('${o.id}')">Jadwalkan tindak lanjut</button>`:''}</div></article>`}).join('')||empty('Tidak ada tagihan pada status ini. ✓')}</section>`;
}
function verificationHTML(){
 const list=state.payments,tabs=workflowTabs([['review','Perlu diperiksa',list.filter(p=>p.status==='review').length],['deferred','Ditunda',list.filter(p=>p.status==='deferred').length],['history','Riwayat',list.filter(p=>['paid','rejected'].includes(p.status)).length]]);
 const rows=list.filter(p=>(workflowTab==='history'?['paid','rejected'].includes(p.status):p.status===workflowTab)&&((tenantById(p.tenant)?.name||'')+' '+p.date).toLowerCase().includes(search.toLowerCase())).slice().sort((a,b)=>b.date.localeCompare(a.date));
 return `<section class="panel"><div class="panel-head"><div><h2>Pemeriksaan transfer</h2><p>Semua periode · transfer beberapa bulan tampil sekali</p></div></div>${tabs}<div class="toolbar"><input type="search" aria-label="Cari pembayaran" placeholder="Cari nama atau tanggal transfer…" value="${esc(search)}" oninput="search=this.value;refreshTransfers()"></div><div id="transfer-rows">${transferRows(rows)}</div></section>`;
}
function refreshTransfers(){const focused=$('input[aria-label="Cari pembayaran"]'),start=focused.selectionStart;$('#content').innerHTML=verificationHTML();const input=$('input[aria-label="Cari pembayaran"]');input.focus();input.setSelectionRange(start,start)}
function transferRows(rows){return rows.map(p=>{const t=tenantById(p.tenant);return `<article class="work-row"><div class="work-person"><span class="avatar sage">${esc(initials(t))}</span><div><b>${esc(t.name)}</b><small>Kamar ${esc(room(t).name)} · ${rangeLabel(p.period,Billing.count(p))}</small><small>Transfer ${esc(p.date)}${p.status==='deferred'?' · '+esc(p.history?.at(-1)?.reason||'Ditunda'):''}</small></div></div><div class="work-amount"><b>${money(p.amount)}</b><small>total transfer · ${Billing.count(p)} bulan</small><span class="badge ${p.status==='paid'?'paid':'review'}">${transferLabels[p.status]}</span></div><button class="secondary" onclick="reviewTransfer('${p.id}')">${['paid','rejected'].includes(p.status)?'Lihat catatan':'Periksa pembayaran'} →</button></article>`}).join('')||empty('Tidak ada transfer pada status ini. ✓')}
function renewalHTML(){
 const list=renewals(),labels=[['needs_asking','Perlu ditanya'],['awaiting_answer','Menunggu jawaban'],['ready_to_renew','Siap diperbarui'],['move_out_planned','Rencana keluar'],['history','Riwayat']];
 const tabs=workflowTabs(labels.map(([id,label])=>[id,label,list.filter(o=>id==='history'?['renewed','closed'].includes(o.state):o.state===id).length]));
 const rows=list.filter(o=>workflowTab==='history'?['renewed','closed'].includes(o.state):o.state===workflowTab).sort((a,b)=>a.end.localeCompare(b.end));
 return `<div class="notice">Tanyakan mulai 30 hari sebelum akhir sewa. Status pembayaran tidak mengubah keputusan perpanjangan. Periode baru dibuat setelah kesepakatan disimpan.</div><section class="panel"><div class="panel-head"><div><h2>Keputusan akhir periode</h2><p>Rencana keluar tetap terlihat sampai keberangkatan dikonfirmasi.</p></div></div>${tabs}${rows.map(o=>{const t=tenantById(o.tenant),record=state.renewals[o.id];return `<article class="work-row"><div class="work-person"><span class="avatar sage">${esc(initials(t))}</span><div><b>${esc(t.name)}</b><small>Kamar ${esc(room(t).name)} · ${o.months} bulan</small><small>Akhir sewa ${esc(o.end)}${record?.nextFollowUp?' · Tindak lanjut '+esc(record.nextFollowUp)+(record.nextFollowUp<=todayISO()?' (sudah waktunya)':''):''}${record?.plannedEnd?' · Rencana keluar '+esc(record.plannedEnd):''}</small></div></div><div class="work-actions">${o.state==='needs_asking'?`<button class="primary" onclick="reminder('${o.tenant}','${o.id}','renewal')">Tanya kelanjutan</button>`:''}${['needs_asking','awaiting_answer','ready_to_renew','move_out_planned'].includes(o.state)?`<button class="secondary" onclick="renewalAnswer('${o.id}')">Catat jawaban</button>`:''}${o.state==='awaiting_answer'?`<button class="text-button" onclick="reminder('${o.tenant}','${o.id}','renewal')">Tindak lanjuti pertanyaan</button>`:''}${o.state==='ready_to_renew'?`<button class="primary" onclick="renewAgreement('${o.id}')">Perbarui sewa</button>`:''}${o.state==='move_out_planned'?`<button class="primary" onclick="closeTenancy('${o.id}')">Konfirmasi keluar</button>`:''}${['renewed','closed'].includes(o.state)?`<span class="badge paid">${o.state==='renewed'?'Diperpanjang':'Selesai menghuni'}</span>`:''}</div></article>`}).join('')||empty('Tidak ada perpanjangan pada status ini. ✓')}</section>`;
}
function recordsHTML(){
 const occupied=state.tenants.filter(t=>!t.endDate),tabs=`<div class="tabs records-tabs"><button class="${recordTab==='tenants'?'active':''}" onclick="setRecordTab('tenants')">Penghuni</button><button class="${recordTab==='rooms'?'active':''}" onclick="setRecordTab('rooms')">Kamar</button><button class="secondary" onclick="${recordTab==='rooms'?'editRoom':'editTenant'}()">＋ Tambah ${recordTab==='rooms'?'kamar':'penghuni'}</button></div>`;
 if(recordTab==='tenants')return `<section class="panel">${tabs}<div class="toolbar"><input type="search" placeholder="Cari nama atau kamar…" aria-label="Cari penghuni" oninput="search=this.value;renderTenants()"><span class="badge paid">${occupied.length} penghuni aktif</span></div><div class="table-wrap" id="tenant-table"></div></section>`;
 return tabs+`<div class="notice">${state.rooms.length} kamar · ${occupied.length} terisi · ${state.rooms.length-occupied.length} tersedia</div><div class="rooms">${state.rooms.map(r=>{const t=occupied.find(t=>t.room===r.id);return `<article class="room"><span>▤</span><div class="room-bottom"><h3>Kamar ${esc(r.name)}</h3><span class="badge ${t?'paid':'soon'}">${t?'Terisi':'Tersedia'}</span></div><p>${esc(r.note)}</p><b>${money(r.price)} <small>/ bulan acuan</small></b><div class="room-bottom"><span>${t?esc(t.name):'Tersedia'}</span><button class="text-button" onclick="editRoom('${r.id}')">Edit →</button></div></article>`}).join('')}</div>`;
}
function reminder(id,itemId,kind='collection'){
 const t=tenantById(id),o=kind==='renewal'?renewalById(itemId):(obligationById(itemId)||obligations().find(o=>o.tenant===id&&!['settled','under_review'].includes(o.state)));
 if(!o)return toast('Tidak ada tagihan yang perlu dihubungi. Buka Perpanjangan sewa untuk menanyakan kelanjutan.');
 const defaultId=kind==='renewal'?'renewal':o.state==='follow_up'?'late':'rent';selectedTemplate=state.templates.some(t=>t.id===defaultId)?defaultId:state.templates[0].id;
 const text=()=>{const template=state.templates.find(t=>t.id===selectedTemplate)||state.templates[0],values={nama:t.name,kamar:room(t).name,bulan:periodName(o.period),periode:rangeLabel(o.period,o.months),nominal:money(o.uncovered??o.agreement.total),tanggal:dateLabel(new Date((o.due||o.agreement.start)+'T00:00:00')),tenure:o.months+' bulan',akhir:dateLabel(new Date(o.end+'T00:00:00'))};return template.body.replace(/\{(nama|kamar|bulan|periode|nominal|tanggal|tenure|akhir)\}/g,(_,k)=>values[k])};
 modal('Siapkan pesan WhatsApp',`<div class="message-recipient"><b>${esc(t.name)} · Kamar ${esc(room(t).name)}</b><small>${esc(t.phone)} · ${rangeLabel(o.period,o.months)}</small></div><label>Template<select id="message-template">${templateOptions(selectedTemplate)}</select></label><label>Pesan<textarea id="message" rows="8">${esc(text())}</textarea></label><label>Tanggal tindak lanjut (opsional)<input id="next-follow-up" type="date" min="${todayISO()}"></label><p class="field-help">Buka dan kirim manual di WhatsApp, lalu konfirmasi di sini. Tanpa tanggal, status tetap menunggu sampai ada perkembangan. Jangan kirim ke nomor data contoh.</p><div class="actions"><button class="secondary" id="copy-message">Salin pesan</button><button class="primary" id="open-wa">Buka WhatsApp ↗</button></div><div class="actions"><button class="secondary" id="sent-confirm">Saya sudah mengirim pesan ✓</button></div>`);
 $('#message-template').onchange=e=>{selectedTemplate=e.target.value;$('#message').value=text()};
 $('#copy-message').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);toast('Pesan disalin.')}catch{$('#message').select();toast('Pilih dan salin teks pesan.')}};
 $('#open-wa').onclick=()=>{let phone=t.phone.replace(/\D/g,'');if(phone.startsWith('0'))phone='62'+phone.slice(1);window.open('https://wa.me/'+phone+'?text='+encodeURIComponent($('#message').value),'_blank','noopener,noreferrer')};
 $('#sent-confirm').onclick=()=>{const next=$('#next-follow-up').value;if(next&&next<todayISO())return toast('Pilih tanggal hari ini atau setelahnya.');const entry={tenant:id,obligation:o.id,period:o.period,kind,templateId:selectedTemplate,message:$('#message').value,date:new Date().toISOString(),nextFollowUp:next||null};if(mutateAndSave(()=>{state.reminders.push(entry);if(kind==='renewal'){const previous=state.renewals[o.id]||{};state.renewals[o.id]={...previous,state:previous.state&&previous.state!=='needs_asking'?previous.state:'awaiting_answer',nextFollowUp:entry.nextFollowUp,history:[...(previous.history||[]),{event:'question_sent',at:entry.date}]}}})){closeModal();render();toast('Pesan ditandai terkirim.')}};
}
function scheduleFollowUp(id){const o=obligationById(id);if(!o)return;modal('Jadwalkan tindak lanjut',`<form id="follow-up-form"><label>Tanggal tindak lanjut<input name="date" type="date" required min="${todayISO()}" value="${o.followUp||todayISO()}"></label><div class="actions"><button class="primary">Simpan jadwal</button></div></form>`);$('#follow-up-form').onsubmit=e=>{e.preventDefault();const date=e.target.elements.date.value;if(date<todayISO())return;if(mutateAndSave(()=>{const records=state.reminders.filter(r=>r.obligation===id||(!r.kind&&r.tenant===o.tenant&&r.period===o.period));const last=records.at(-1);if(last){last.nextFollowUp=date}else state.reminders.push({tenant:o.tenant,obligation:id,period:o.period,kind:'collection',date:new Date().toISOString(),nextFollowUp:date})})){closeModal();render();toast('Jadwal tersimpan.')}}}
function recordPayment(id,start){
 const list=state.tenants.filter(t=>(!t.endDate)||obligations().some(o=>o.tenant===t.id&&o.balance>0));if(!list.length)return toast('Tambahkan penghuni terlebih dahulu.');
 if(id)return paymentForm(id,start);
 modal('Catat pembayaran',`<form id="choose-payment"><label>Penghuni<select name="tenant">${list.map(t=>`<option value="${t.id}">${esc(t.name)} · Kamar ${esc(room(t).name)}</option>`).join('')}</select></label><div class="actions"><button class="primary">Lanjut →</button></div></form>`);$('#choose-payment').onsubmit=e=>{e.preventDefault();paymentForm(e.target.elements.tenant.value)};
}
function pay(id){const t=tenantById(id),p=Billing.findPayment(state.payments,id,period());p?reviewTransfer(p.id):recordPayment(id,period())}
function paymentForm(id,start,existingId){
 const t=tenantById(id),existing=state.payments.find(p=>p.id===existingId);
 if(existing?.status==='paid')return toast('Batalkan verifikasi sebelum mengoreksi catatan.');
 const o=obligations().find(o=>o.tenant===id&&o.uncovered>0),defaults=Workflows.paymentDefaults(state,id,start||o?.period),first=existing?.period||defaults.period,months=existing?Billing.count(existing):defaults.months;
 modal(existing?'Koreksi catatan transfer':'Catat pembayaran',`<div class="message-recipient"><b>${esc(t.name)} · Kamar ${esc(room(t).name)}</b></div><form id="pay-form"><div class="form-grid"><label>Mulai bulan yang dibayar<input type="month" name="period" min="${t.start.slice(0,7)}" required value="${first}"></label><label>Jumlah bulan<input type="number" name="months" min="1" max="12" step="1" required value="${months}"></label></div><div id="coverage-preview" class="hint" aria-live="polite"></div><div class="form-grid"><label>Total nominal transfer (Rp)<input name="amount" type="number" min="1" step="1" required></label><label>Tanggal transfer<input name="date" type="date" required max="${todayISO()}" value="${existing?.date||todayISO()}"></label></div><label>Catatan<input name="note" maxlength="200" value="${esc(existing?.note||'')}"></label>${existing?'<label>Alasan koreksi<input name="correction" required maxlength="200"></label>':''}<label>Bukti (JPG / PNG / WebP, maks. 1 MB)<input id="receipt" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="field-help">Pembayaran harus mencakup penuh bulan yang dipilih. Cicilan, diskon, dan kelebihan bayar belum didukung. Periksa mutasi rekening sebelum menandai lunas.</p><p id="payment-error" class="form-error" role="alert"></p><div class="actions"><button class="secondary" type="submit" name="action" value="review">Simpan untuk diperiksa</button><button class="primary" type="submit" name="action" value="paid">Dana masuk · tandai lunas</button></div></form>`);
 const form=$('#pay-form'),allocation=()=>{const n=Number(form.elements.months.value),p=form.elements.period.value;return n>=1&&n<=12&&Number.isInteger(n)&&p?Array.from({length:n},(_,i)=>Billing.monthlyCharge(t,Billing.shift(p,i),room(t).price)):[]};
 function preview(){const amounts=allocation();form.elements.amount.value=amounts.reduce((s,v)=>s+v,0);$('#coverage-preview').innerHTML=amounts.length?`<b>${rangeLabel(form.elements.period.value,amounts.length)}</b><div class="allocation-preview">${amounts.map((v,i)=>`<span>${periodName(Billing.shift(form.elements.period.value,i))}<b>${money(v)}</b></span>`).join('')}</div>`:'Pilih periode dan jumlah bulan.'}
 form.elements.period.oninput=preview;form.elements.months.oninput=preview;preview();if(existing)form.elements.amount.value=existing.amount;let submitting=false;
 form.onsubmit=async e=>{e.preventDefault();if(submitting)return;const f=new FormData(form),action=e.submitter?.value||'review',amounts=allocation(),amount=Number(f.get('amount')),period=f.get('period'),n=Number(f.get('months')),fail=msg=>$('#payment-error').textContent=msg;
 if(!amounts.length||amounts.some(v=>v<=0)||period<t.start.slice(0,7))return fail('Pilih bulan dalam kesepakatan sewa yang sudah disimpan. Perbarui sewa dahulu untuk periode berikutnya.');
 if(!Number.isSafeInteger(amount)||amount!==amounts.reduce((s,v)=>s+v,0))return fail('Nominal harus sama dengan total alokasi bulan yang dipilih.');
 if(f.get('date')>todayISO())return fail('Tanggal transfer tidak boleh setelah hari ini.');
 const p={id:existing?.id||crypto.randomUUID(),tenant:id,period,months:n,allocations:amounts,amount,status:action,date:f.get('date'),note:f.get('note').trim(),receipt:existing?.receipt||null,history:[...(existing?.history||[]),{event:existing?'corrected':action==='paid'?'verified_on_entry':'recorded',from:existing?.status,to:action,at:new Date().toISOString(),...(existing?{reason:f.get('correction').trim(),previous:{period:existing.period,months:Billing.count(existing),amount:existing.amount,date:existing.date,allocations:existing.allocations}}:{})}]};
 if(Billing.overlaps(state.payments,p))return fail('Ada pembayaran aktif pada bulan yang dipilih. Buka Verifikasi pembayaran untuk memeriksa transfer tersebut.');
 submitting=true;const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
 try{const file=$('#receipt').files[0];if(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1024*1024)return fail('Gunakan JPG, PNG, atau WebP maksimal 1 MB.');p.receipt=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}if(mutateAndSave(()=>{state.payments=state.payments.filter(item=>item.id!==p.id);state.payments.push(p)})){closeModal();go('verify');workflowTab=action==='paid'?'history':'review';render();toast(action==='paid'?'Pembayaran terverifikasi tersimpan di Riwayat.':'Tersimpan di Verifikasi pembayaran.')}}catch{fail('Bukti gagal dibaca. Pilih ulang berkas.')}finally{submitting=false;buttons.forEach(b=>b.disabled=false)}};
}
function reviewTransfer(id){
 const p=state.payments.find(p=>p.id===id);if(!p)return;const t=tenantById(p.tenant),allocations=Billing.covered(p);
 modal('Periksa pembayaran',`<div class="message-recipient"><b>${esc(t.name)} · Kamar ${esc(room(t).name)}</b><small>${rangeLabel(p.period,Billing.count(p))} · transfer ${esc(p.date)}</small></div><span class="badge ${p.status==='paid'?'paid':'review'}">${transferLabels[p.status]}</span><div class="payment-money">${money(p.amount)} <small>total transfer</small></div><div class="allocation-preview">${allocations.map(m=>`<span>${periodName(m)}<b>${money(Billing.monthlyAmount(p,m))}</b></span>`).join('')}</div><p>${esc(p.note||'Tanpa catatan')}</p>${p.receipt?`<img class="receipt-img" src="${p.receipt}" alt="Bukti transfer">`:empty('Tidak ada lampiran bukti. Periksa mutasi rekening.')}<label>Alasan / catatan keputusan<input id="review-reason" maxlength="200" placeholder="Wajib untuk menunda, menolak, atau membatalkan"></label><p id="review-error" class="form-error" role="alert"></p><div class="actions review-actions">${p.status!=='paid'?`<button class="secondary" onclick="paymentForm('${p.tenant}','${p.period}','${p.id}')">Koreksi catatan</button>`:''}${['review','deferred'].includes(p.status)?`<button class="danger" onclick="applyTransferEvent('${id}','reject')">Tolak transfer</button><button class="secondary" onclick="applyTransferEvent('${id}','${p.status==='deferred'?'resume':'defer'}')">${p.status==='deferred'?'Lanjutkan pemeriksaan':'Tunda'}</button><button class="primary" onclick="applyTransferEvent('${id}','verify')">Dana masuk · tandai lunas</button>`:p.status==='paid'?`<button class="danger" onclick="applyTransferEvent('${id}','undo')">Batalkan status lunas</button>`:`<button class="secondary" onclick="applyTransferEvent('${id}','reopen')">Buka pemeriksaan lagi</button>`}</div><p class="field-help">Membatalkan lunas mengembalikan transfer ke pemeriksaan. Tolak transfer jika dana tidak diterima agar tagihan kembali ditindaklanjuti.</p><details><summary>Riwayat pemeriksaan</summary>${(p.history||[]).map(h=>`<p class="audit-entry">${esc(h.at)} · ${esc(({corrected:'Catatan dikoreksi',recorded:'Dicatat',verified_on_entry:'Diverifikasi saat dicatat',verify:'Diverifikasi',defer:'Ditunda',resume:'Pemeriksaan dilanjutkan',reject:'Ditolak',undo:'Verifikasi dibatalkan',reopen:'Dibuka kembali'})[h.event]||h.event)}${h.reason?' · '+esc(h.reason):''}</p>`).join('')||'<p>Catatan lama tanpa riwayat keputusan.</p>'}</details>`);
}
function applyTransferEvent(id,event){
 const p=state.payments.find(p=>p.id===id),fail=msg=>$('#review-error').textContent=msg;
 try{if(['verify','reopen','undo'].includes(event)&&Billing.overlaps(state.payments,p))return fail('Alokasi bertumpang tindih dengan pembayaran pengganti. Periksa catatan lain terlebih dahulu.');const changed=Workflows.transitionPayment(p,event,$('#review-reason').value,new Date().toISOString());if(mutateAndSave(()=>{state.payments[state.payments.findIndex(p=>p.id===id)]=changed;if(event==='reject'){for(const o of obligations().filter(o=>o.tenant===p.tenant&&Billing.covered(p).some(m=>Billing.index(m)>=Billing.index(o.period)&&Billing.index(m)<Billing.index(o.period)+o.months))){state.reminders.push({tenant:p.tenant,obligation:o.id,period:o.period,kind:'collection',date:new Date().toISOString(),nextFollowUp:todayISO(),decision:'transfer_rejected'})}}})){closeModal();render();toast('Keputusan tersimpan; seluruh alokasi diperbarui.')}}catch(e){fail(e.message.startsWith('Reason required')?'Isi alasan keputusan terlebih dahulu.':'Perubahan status ini tidak tersedia.')}
}
function saveRenewalEvent(id,next,details={}){const previous=state.renewals[id]||{};state.renewals[id]={...previous,...details,state:next,history:[...(previous.history||[]),{from:previous.state||'needs_asking',to:next,at:new Date().toISOString(),...details}]}}
function renewalAnswer(id){const o=renewalById(id);if(!o)return;modal('Catat jawaban penghuni',`<form id="renew-answer"><label>Keputusan<select name="answer"><option value="ready_to_renew">Setuju lanjut</option><option value="awaiting_answer">Belum memutuskan</option><option value="move_out_planned">Tidak lanjut</option></select></label><label>Rencana tanggal keluar (untuk tidak lanjut)<input name="end" type="date" min="${o.agreement.start}" value="${state.renewals[id]?.plannedEnd||o.end}"></label><label>Catatan jawaban<textarea name="note" maxlength="300" rows="3"></textarea></label><div class="actions"><button class="primary">Simpan jawaban</button></div></form>`);$('#renew-answer').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next=f.get('answer');if(next==='move_out_planned'&&!f.get('end'))return toast('Isi rencana tanggal keluar.');if(mutateAndSave(()=>saveRenewalEvent(id,next,{note:f.get('note').trim(),plannedEnd:next==='move_out_planned'?f.get('end'):null}))){closeModal();render();toast('Jawaban tersimpan.')}}}
function renewAgreement(id){
 const o=renewalById(id),t=o&&tenantById(o.tenant);if(!t||o.state!=='ready_to_renew')return;
 modal('Simpan periode sewa berikutnya',`<form id="renew-agreement"><div class="message-recipient"><b>${esc(t.name)}</b><small>Periode sebelumnya berakhir ${o.end}. Pembayaran dicatat terpisah.</small></div><label>Awal periode baru<input name="start" type="date" required value="${o.nextStart}" min="${o.nextStart}"></label><label>Lama sewa<select name="months">${termOptions(o.agreement.months)}</select></label><label>Total harga seluruh periode (Rp)<input name="total" type="number" min="1" step="1" required value="${o.agreement.total}"></label><p class="field-help">Awal periode mengikuti hari berikutnya agar tidak ada jeda atau tagihan ganda. Untuk perubahan tanggal khusus, koreksi kesepakatan melalui data penghuni.</p><p class="form-error" id="renew-error" role="alert"></p><div class="actions"><button class="primary">Simpan kesepakatan baru</button></div></form>`);
 $('#renew-agreement').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),start=f.get('start'),months=Number(f.get('months')),total=Number(f.get('total')),fail=msg=>$('#renew-error').textContent=msg;
 if(start!==o.nextStart)return fail('Gunakan awal periode '+o.nextStart+' agar tidak ada jeda.');
 if(!Billing.termOptions.includes(months)||!Number.isSafeInteger(total)||total<=0)return fail('Isi lama dan total harga sewa yang valid.');
 if(t.endDate||t.agreements.some(a=>a.start.slice(0,7)>o.period))return fail('Sudah ada periode berikutnya atau penghuni sudah keluar.');
 if(mutateAndSave(()=>{const agreement={start,months,total,day:o.agreement.day||Number(start.slice(8,10))};t.agreements.push(agreement);Object.assign(t,{term:months,termRate:total,termStart:start,day:agreement.day});saveRenewalEvent(id,'renewed',{successor:start})})){closeModal();render();toast('Kesepakatan baru tersimpan. Pembayaran belum dicatat.')}};
}
function closeTenancy(id){const o=renewalById(id);if(!o||o.state!=='move_out_planned')return;const t=tenantById(o.tenant),record=state.renewals[id];modal('Konfirmasi penghuni keluar',`<form id="departure"><label>Tanggal keluar<input name="end" type="date" min="${t.start}" max="${todayISO()}" required value="${record.plannedEnd>todayISO()?todayISO():record.plannedEnd||todayISO()}"></label><p class="field-help">Kamar kembali tersedia setelah dikonfirmasi. Tagihan lama tetap tersimpan; tagihan bulan keluar tetap penuh.</p><p class="form-error" id="departure-error" role="alert"></p><div class="actions"><button class="primary">Konfirmasi keluar</button></div></form>`);$('#departure').onsubmit=e=>{e.preventDefault();const end=e.target.elements.end.value;if(end<t.start||end>todayISO())return;if(state.payments.some(p=>p.tenant===t.id&&p.status!=='rejected'&&Billing.covered(p).some(m=>m>end.slice(0,7))))return $('#departure-error').textContent='Ada transfer untuk bulan setelah keluar. Koreksi cakupan pembayaran sebelum menutup sewa.';if(t.agreements.some(a=>a.start>end))return $('#departure-error').textContent='Ada kesepakatan setelah tanggal keluar. Koreksi kesepakatan dahulu.';if(mutateAndSave(()=>{t.endDate=end;saveRenewalEvent(id,'closed',{departure:end})})){closeModal();render();toast('Keberangkatan tercatat; kamar tersedia.')}}}
render();
function tenantDetail(id){const t=tenantById(id);modal('Riwayat penghuni',`<div class="message-recipient"><b>${esc(t.name)} · Kamar ${esc(room(t).name)}</b><small>${esc(t.phone)}${t.endDate?' · Keluar '+esc(t.endDate):''}</small></div><h3>Kesepakatan sewa</h3>${t.agreements.map(a=>`<p>${esc(a.start)} · ${a.months} bulan · ${money(a.total)} total</p>`).join('')}<h3>Pembayaran</h3>${state.payments.filter(p=>p.tenant===id).map(p=>`<p><button class="text-button" onclick="reviewTransfer('${p.id}')">${rangeLabel(p.period,Billing.count(p))} · ${money(p.amount)} · ${transferLabels[p.status]} →</button></p>`).join('')||empty('Belum ada pembayaran.')}<h3>Pesan dan tindak lanjut</h3>${state.reminders.filter(r=>r.tenant===id).map(r=>`<details><summary>${esc(r.date?.slice(0,10))} · ${r.kind==='renewal'?'Perpanjangan':r.decision?'Keputusan pembayaran':'Penagihan'}</summary><p class="message-history">${esc(r.message||r.decision||'Jadwal tindak lanjut')}${r.nextFollowUp?'\nTindak lanjut: '+esc(r.nextFollowUp):''}</p></details>`).join('')||empty('Belum ada pesan tercatat.')}`)}
